    if math_type(p16) == "float" then p16 = math_tointeger((math_modf(p16))) or 0 end
    return CreateScriptVehicleGenerator(coords.x, coords.y, coords.z, heading, p4, p5, modelHash, p7, p8, p9, p10, p11, p12, p13, p14, p15, p16)
