    if math_type(duration) == "float" then duration = math_tointeger((math_modf(duration))) or 0 end
    local t_mode = type(mode)
    if t_mode == "string" then mode = GetHashKey(mode) elseif t_mode == "table" then mode = mode.handle end
    StartVehicleHorn(self.handle, duration, mode, forever)
    return self
  end
end

