local CreateVehicle, IsModelInCdimage, IsModelAVehicle = CreateVehicle, IsModelInCdimage, IsModelAVehicle
local SetVehicleOnGroundProperly = SetVehicleOnGroundProperly

---@param model fx.Model|integer|string
---@param position vector3|vector4
---@param heading? number
---@param options? fx.VehicleCreateOptions
---@return fx.Vehicle?
statics.createRaw = function(model, position, heading, options)
  local hash = rt.hash(model)
  if not rt.requireLoaded("Vehicle.createRaw", hash, model) then return nil end
  local net = not (options and options.networked == false)
  local mission = not (options and options.missionEntity == false)
  local h = CreateVehicle(hash, position.x, position.y, position.z, rt.heading(position, heading), net, mission)
  local v = T.wrap(h)
  if v then
    if net then rt.netIntent[v] = true end
    if options and options.placeOnGround then SetVehicleOnGroundProperly(h) end
  end
  return v
end

---@param hash integer
---@return boolean
local function isVehicleModel(hash) return IsModelInCdimage(hash) and IsModelAVehicle(hash) end
