  { "doorSpeaker", 31 }, { "seats", 32 }, { "steeringWheel", 33 }, { "shifter", 34 }, { "plaque", 35 }, { "speakers", 36 },
  { "trunk", 37 }, { "hydraulics", 38 }, { "engineBlock", 39 }, { "airFilter", 40 }, { "struts", 41 }, { "archCover", 42 },
  { "aerials", 43 }, { "trimB", 44 }, { "tank", 45 }, { "leftDoor", 46 }, { "rightDoor", 47 }, { "livery", 48 },
  { "lightbar", 49 },
}
---@type table<string, integer>
local SLOT = {}
---@type table<string, boolean>
local TOGGLE = {}
for _, m in ipairs(MODS) do SLOT[m[1]] = m[2]; TOGGLE[m[1]] = m[3] or false end

---@type integer[]
local TYRES = { 0, 1, 2, 3, 4, 5, 45, 47 }
---@type table<string, integer> eNeonIndex
local NEONS = { left = 2, right = 1, front = 3, back = 0 }

---@param key any A mod key, checked
---@param label string
---@return integer
local function slotOf(key, label)
  local slot = SLOT[key]
  if not slot then fail(("%s: unknown mod '%s' (see fx.Enum.VehicleMods)"):format(label, tostring(key))) end
  return slot
end

-- the mod kit must be 0 before reading the mod counts or setting a mod
---@param h integer
local function kit(h) if GetVehicleModKit(h) ~= 0 then SetVehicleModKit(h, 0) end end

---@param v any { r, g, b }, checked
---@param label string
---@return integer r, integer g, integer b
local function rgb(v, label)
  if type(v) ~= "table" or type(v[1]) ~= "number" or type(v[2]) ~= "number" or type(v[3]) ~= "number" then
    fail(("%s: expected { r, g, b }, got %s"):format(label, tostring(v)))
  end
  return rt.int(v[1]), rt.int(v[2]), rt.int(v[3])
end

---@param list any A list of indexes, checked
---@param label string
---@return table<integer, true>
local function indexSet(list, label)
  if type(list) ~= "table" then fail(("%s: expected a list of indexes, got %s"):format(label, tostring(list))) end
  local s = {}
  for _, i in ipairs(list) do s[rt.int(tonumber(i))] = true end
  return s
end

---@param h integer
---@param key string
---@return integer|boolean
local function getMod(h, key)
  local slot = slotOf(key, "vehicle.mods")
  if TOGGLE[key] then return IsToggleModOn(h, slot) end
  return GetVehicleMod(h, slot)
end

---@param h integer
---@param key string
---@param v any Checked
---@param custom? boolean Custom tyres (wheel slots)
local function setMod(h, key, v, custom)
  local slot = slotOf(key, "vehicle.mods")
  kit(h)
  if TOGGLE[key] then
    if type(v) ~= "boolean" then fail(("vehicle.mods.%s: expected a boolean, got %s"):format(key, tostring(v))) end
    ToggleVehicleMod(h, slot, v)
    return
  end
  v = rt.int(v)
  if mathType(v) ~= "integer" then fail(("vehicle.mods.%s: expected an integer, got %s"):format(key, tostring(v))) end
  if fx.debug then
    local n = GetNumVehicleMods(h, slot)
    if v < -1 or v >= n then fail(("vehicle.mods.%s: %d is out of range (-1 to %d on this vehicle)"):format(key, v, n - 1)) end
  end
  local wheels = slot == 23 or slot == 24
  if custom == nil then custom = wheels and GetVehicleModVariation(h, slot) or false end
  -- stock wheels (-1) can still carry custom tyres: RemoveVehicleMod would drop them
  if v == -1 and not (wheels and custom) then RemoveVehicleMod(h, slot); return end
  SetVehicleMod(h, slot, v, custom)
end

---@param h integer
---@return fx.VehicleModsData
local function getMods(h)
  kit(h)
  local t = { wheelType = GetVehicleWheelType(h), customTyres = GetVehicleModVariation(h, 23) }
  for _, m in ipairs(MODS) do
    local key, slot = m[1], m[2]
    if m[3] then
      t[key] = IsToggleModOn(h, slot)
    else
      local v = GetVehicleMod(h, slot)
      if v ~= -1 or GetNumVehicleMods(h, slot) > 0 then t[key] = v end
    end
  end
  return t
end

---@param h integer
---@param t fx.VehicleModsData
local function setMods(h, t)
  for k in pairs(t) do
    if k ~= "wheelType" and k ~= "customTyres" then slotOf(k, "mods") end
  end
  kit(h)
  -- the wheel type first: it decides which wheel list the wheel mods index
  local wheelType = t.wheelType
  if wheelType ~= nil then SetVehicleWheelType(h, rt.int(wheelType)) end
  for _, m in ipairs(MODS) do
    local v = t[m[1]]
    if v ~= nil then
      local custom
      if m[2] == 23 or m[2] == 24 then custom = t.customTyres end
      setMod(h, m[1], v, custom)
    end
  end
  if t.customTyres ~= nil then
    local custom = t.customTyres and true or false
    if t.frontWheels == nil then SetVehicleMod(h, 23, GetVehicleMod(h, 23), custom) end
    -- motorbikes keep a separate flag on the rear wheel
    if t.rearWheels == nil and IsThisModelABike(GetEntityModel(h)) then SetVehicleMod(h, 24, GetVehicleMod(h, 24), custom) end
  end
end

---@param h integer
---@param key string
---@param index? integer The current part when nil
---@return string?
local function modLabel(h, key, index)
  local slot = slotOf(key, "vehicle.mods:label")
  if TOGGLE[key] then return nil end
  kit(h)
  if index == nil then index = GetVehicleMod(h, slot) end
  index = rt.int(index)
  if index < 0 then return nil end
  local name = GetModTextLabel(h, slot, index)
  if not name or name == "" then return nil end
  local text = GetLabelText(name)
  if not text or text == "NULL" then return name end
  return text
end

---@alias fx.VehicleColorValue integer|integer[]|false|table<string, boolean>

---@class fx.VehicleColorAccess
---@field get fun(h: integer): fx.VehicleColorValue
---@field set fun(h: integer, v: any) v is checked

---@type table<string, fx.VehicleColorAccess>
local COLORS = {}
COLORS.primary = {
  get = function(h) return (GetVehicleColours(h)) end,
  set = function(h, v) local _, s = GetVehicleColours(h); SetVehicleColours(h, rt.int(v), s) end,
}
COLORS.secondary = {
  get = function(h) local _, s = GetVehicleColours(h); return s end,
  set = function(h, v) local p = GetVehicleColours(h); SetVehicleColours(h, p, rt.int(v)) end,
}
COLORS.pearl = {
  get = function(h) return (GetVehicleExtraColours(h)) end,
  set = function(h, v) local _, w = GetVehicleExtraColours(h); SetVehicleExtraColours(h, rt.int(v), w) end,
}
COLORS.wheels = {
  get = function(h) local _, w = GetVehicleExtraColours(h); return w end,
  set = function(h, v) local p = GetVehicleExtraColours(h); SetVehicleExtraColours(h, p, rt.int(v)) end,
}
---@param isCustom fun(h: integer): boolean
---@param get fun(h: integer): integer, integer, integer
---@param set fun(h: integer, r: integer, g: integer, b: integer)
---@param clear fun(h: integer)
---@param name string
---@return fx.VehicleColorAccess
local function customColor(isCustom, get, set, clear, name)
  return {
    get = function(h) if isCustom(h) then return { get(h) } end return false end,
    set = function(h, v)
      if v == false then clear(h) else set(h, rgb(v, "vehicle.colors." .. name)) end
    end,
  }
end
COLORS.primaryRgb = customColor(GetIsVehiclePrimaryColourCustom, GetVehicleCustomPrimaryColour, SetVehicleCustomPrimaryColour,
  ClearVehicleCustomPrimaryColour, "primaryRgb")
COLORS.secondaryRgb = customColor(GetIsVehicleSecondaryColourCustom, GetVehicleCustomSecondaryColour,
  SetVehicleCustomSecondaryColour, ClearVehicleCustomSecondaryColour, "secondaryRgb")
COLORS.interior = {
  get = function(h) return (GetVehicleInteriorColor(h)) end,
  set = function(h, v) SetVehicleInteriorColor(h, rt.int(v)) end,
}
COLORS.dashboard = {
  get = function(h) return (GetVehicleDashboardColor(h)) end,
  set = function(h, v) SetVehicleDashboardColor(h, rt.int(v)) end,
}
COLORS.xenon = {
  get = function(h) return GetVehicleXenonLightsColor(h) end,
  set = function(h, v) SetVehicleXenonLightsColor(h, rt.int(v)) end,
}
COLORS.xenonRgb = {
  get = function(h)
    local has, r, g, b = GetVehicleXenonLightsCustomColor(h)
    if has and has ~= 0 then return { r, g, b } end
    return false
  end,
  set = function(h, v)
    if v == false then ClearVehicleXenonLightsCustomColor(h) else SetVehicleXenonLightsCustomColor(h, rgb(v, "vehicle.colors.xenonRgb")) end
  end,
}
COLORS.neon = {
  get = function(h) return { GetVehicleNeonLightsColour(h) } end,
  set = function(h, v) SetVehicleNeonLightsColour(h, rgb(v, "vehicle.colors.neon")) end,
}
COLORS.neonEnabled = {
  get = function(h)
    local t = {}
    for side, i in pairs(NEONS) do t[side] = IsVehicleNeonLightEnabled(h, i) end
    return t
  end,
  set = function(h, v)
    if type(v) ~= "table" then fail("vehicle.colors.neonEnabled: expected { left, right, front, back }") end
    for side, on in pairs(v) do
      local i = NEONS[side]
      if not i then fail(("vehicle.colors.neonEnabled: unknown side '%s' (left, right, front, back)"):format(tostring(side))) end
      SetVehicleNeonLightEnabled(h, i, on and true or false)
    end
  end,
}
COLORS.tyreSmoke = {
  get = function(h) return { GetVehicleTyreSmokeColor(h) } end,
  set = function(h, v) SetVehicleTyreSmokeColor(h, rgb(v, "vehicle.colors.tyreSmoke")) end,
}
COLORS.windowTint = {
  get = function(h) return GetVehicleWindowTint(h) end,
  set = function(h, v) SetVehicleWindowTint(h, rt.int(v)) end,
}
COLORS.livery = {
  get = function(h) return GetVehicleLivery(h) end,
  set = function(h, v) SetVehicleLivery(h, rt.int(v)) end,
}
COLORS.roofLivery = {
  get = function(h) return GetVehicleRoofLivery(h) end,
  set = function(h, v) SetVehicleRoofLivery(h, rt.int(v)) end,
}
-- the indexes before the custom colours: SET_VEHICLE_COLOURS clears them
---@type string[]
local COLOR_ORDER = { "primary", "secondary", "pearl", "wheels", "primaryRgb", "secondaryRgb", "interior", "dashboard",
  "xenon", "xenonRgb", "neon", "neonEnabled", "tyreSmoke", "windowTint", "livery", "roofLivery" }

---@param k any A colour key, checked
---@param label string
---@return fx.VehicleColorAccess
local function colorOf(k, label)
  local c = COLORS[k]
  if not c then fail(("%s: unknown key '%s'"):format(label, tostring(k))) end
  return c
end

---@param h integer
---@return fx.VehicleColorsData
local function getColors(h)
  local t = {}
  for _, k in ipairs(COLOR_ORDER) do t[k] = COLORS[k].get(h) end
  return t
end

---@param h integer
---@param t fx.VehicleColorsData
local function setColors(h, t)
  for k in pairs(t) do colorOf(k, "colors") end
  for _, k in ipairs(COLOR_ORDER) do
    if t[k] ~= nil then COLORS[k].set(h, t[k]) end
  end
end

---@param h integer
---@return fx.VehicleDamageData
local function getDamage(h)
  local doors, windows, burst, rims = {}, {}, {}, {}
  for d = 0, 5 do if IsVehicleDoorDamaged(h, d) then doors[#doors + 1] = d end end
  for w = 0, 7 do if not IsVehicleWindowIntact(h, w) then windows[#windows + 1] = w end end
  for _, i in ipairs(TYRES) do
    if IsVehicleTyreBurst(h, i, false) then
      burst[#burst + 1] = i
      if IsVehicleTyreBurst(h, i, true) then rims[#rims + 1] = i end
    end
  end
  return {
    engine = GetVehicleEngineHealth(h), body = GetVehicleBodyHealth(h), tank = GetVehiclePetrolTankHealth(h),
    dirt = GetVehicleDirtLevel(h), brokenDoors = doors, brokenWindows = windows, burstTyres = burst, rimTyres = rims,
  }
end

---@type table<string, true>
local DAMAGE_KEYS = { engine = true, body = true, tank = true, dirt = true, brokenDoors = true, brokenWindows = true,
  burstTyres = true, rimTyres = true }

---@param k any
---@param label string
local function damageKey(k, label)
  if not DAMAGE_KEYS[k] then fail(("%s: unknown key '%s'"):format(label, tostring(k))) end
end

-- A list gives the whole state of its parts: the parts missing from it are repaired. A broken door can only be
-- repaired by SET_VEHICLE_FIXED, which repairs everything: the rest of the damage is then put back.
---@param h integer
---@param t fx.VehicleDamageData
local function setDamage(h, t)
  for k in pairs(t) do damageKey(k, "damage") end
  ---@type fx.VehicleDamageData
  local base = {}
  if t.brokenDoors ~= nil then
    local want = indexSet(t.brokenDoors, "damage.brokenDoors")
    for d = 0, 5 do
      if IsVehicleDoorDamaged(h, d) and not want[d] then
        base = getDamage(h)
        SetVehicleFixed(h)
        break
      end
    end
  end
  ---@param k string
  ---@return any
  local function pick(k) if t[k] ~= nil then return t[k] end return base[k] end
  local burst, rims = pick("burstTyres"), pick("rimTyres")
  if burst ~= nil or rims ~= nil then
    local b = indexSet(burst or {}, "damage.burstTyres")
    local r = indexSet(rims or {}, "damage.rimTyres")
    for _, i in ipairs(TYRES) do
      if b[i] or r[i] then SetVehicleTyreBurst(h, i, r[i] == true, 1000.0)
      elseif burst ~= nil and IsVehicleTyreBurst(h, i, false) then SetVehicleTyreFixed(h, i) end
    end
  end
  local windows = pick("brokenWindows")
  if windows ~= nil then
    local want = indexSet(windows, "damage.brokenWindows")
    for w = 0, 7 do
      if want[w] then
        if IsVehicleWindowIntact(h, w) then SmashVehicleWindow(h, w) end
      elseif not IsVehicleWindowIntact(h, w) then
        FixVehicleWindow(h, w)
      end
    end
  end
  local doors = pick("brokenDoors")
  if doors ~= nil then
    for d in pairs(indexSet(doors, "damage.brokenDoors")) do
      if not IsVehicleDoorDamaged(h, d) then SetVehicleDoorBroken(h, d, true) end
    end
  end
  local v = pick("engine"); if v ~= nil then SetVehicleEngineHealth(h, float(v)) end
  v = pick("body"); if v ~= nil then SetVehicleBodyHealth(h, float(v)) end
  v = pick("tank"); if v ~= nil then SetVehiclePetrolTankHealth(h, float(v)) end
  v = pick("dirt"); if v ~= nil then SetVehicleDirtLevel(h, float(v)) end
end

---@param k any An extra id, checked
---@param label string
---@return integer
local function extraId(k, label)
  local id = rt.int(tonumber(k)) -- a JSON round trip turns the keys into strings
  if mathType(id) ~= "integer" then fail(("%s: invalid extra id '%s'"):format(label, tostring(k))) end
  return id --[[@as integer]]
end

---@param h integer
---@return table<integer, boolean>
local function getExtras(h)
  local t = {}
  for id = 0, 20 do if DoesExtraExist(h, id) then t[id] = IsVehicleExtraTurnedOn(h, id) end end
  return t
end

-- SET_VEHICLE_EXTRA repairs the vehicle: keepDamage puts the damage back (the deformation is lost)
---@param h integer
---@param t table<integer|string, boolean>
---@param keepDamage boolean
local function setExtras(h, t, keepDamage)
  local saved = keepDamage and getDamage(h)
  for k, on in pairs(t) do
    local id = extraId(k, "extras")
    if DoesExtraExist(h, id) then
      SetVehicleExtra(h, id, on and 0 or 1) -- 0 turns the extra on
    elseif fx.debug then
      fail(("vehicle.extras: extra %d does not exist on this vehicle"):format(id))
    end
  end
  if saved then setDamage(h, saved) end
end

---@param h integer
---@return fx.VehicleDetailsData
local function getDetails(h)
  return {
    plate = (GetVehicleNumberPlateText(h) or ""):match("^%s*(.-)%s*$"), plateStyle = GetVehicleNumberPlateTextIndex(h),
    fuel = GetVehicleFuelLevel(h), oil = GetVehicleOilLevel(h),
  }
end

---@param h integer
---@param t fx.VehicleDetailsData
local function setDetails(h, t)
  for k, v in pairs(t) do
    if k == "plate" then
      if type(v) ~= "string" or #v > 8 then fail("details.plate must be a string of at most 8 characters") end
      SetVehicleNumberPlateText(h, v)
    elseif k == "plateStyle" then SetVehicleNumberPlateTextIndex(h, rt.int(v))
    elseif k == "fuel" then SetVehicleFuelLevel(h, float(v))
    elseif k == "oil" then SetVehicleOilLevel(h, float(v))
    else fail(("details: unknown key '%s'"):format(tostring(k))) end
  end
end

-- applied in this order: wheel type and mods, colours, extras (they repair the vehicle), damage, details
---@type fx.VehiclePropertyGroup[]
local GROUPS = { "mods", "colors", "extras", "damage", "details" }
---@type table<string, fun(h: integer): table>
local GET = { mods = getMods, colors = getColors, extras = getExtras, damage = getDamage, details = getDetails }
---@type table<string, fun(h: integer, t: table)>
local SET = { mods = setMods, colors = setColors, damage = setDamage, details = setDetails,
  ---@param h integer
  ---@param t table<integer|string, boolean>
  extras = function(h, t) setExtras(h, t, false) end }

---@param self fx.Vehicle
---@param groups? fx.VehiclePropertyGroup[]
---@return fx.VehicleProperties
methods.getProperties = function(self, groups)
  local h = self.handle
  ---@type table<string, integer|table>
  local t = { model = GetEntityModel(h) }
  if groups == nil then groups = GROUPS end
  if type(groups) ~= "table" then error("vehicle:getProperties: groups must be a list ({ 'mods', 'colors', ... })", 2) end
  for _, g in ipairs(groups) do
    local get = GET[g]
    if not get then error(("vehicle:getProperties: unknown group '%s' (mods, colors, extras, damage, details)"):format(tostring(g)), 2) end
    t[g] = get(h)
  end
  return t --[[@as fx.VehicleProperties]]
end

---@param self fx.Vehicle
---@param props fx.VehicleProperties
---@return fx.Vehicle
methods.setProperties = function(self, props)
  if type(props) ~= "table" then error("vehicle:setProperties: expected a table", 2) end
  local h = self.handle
  if fx.debug and NetworkGetEntityIsNetworked(h) and not NetworkHasControlOfEntity(h) then
    error(tostring(self) .. ":setProperties: this client does not control the vehicle (use setPropertiesAsync)", 2)
  end
  for k, v in pairs(props) do
    if k ~= "model" then
      if not SET[k] then error(("vehicle:setProperties: unknown group '%s' (mods, colors, extras, damage, details)"):format(tostring(k)), 2) end
      if type(v) ~= "table" then error(("vehicle:setProperties: '%s' must be a table"):format(k), 2) end
    end
  end
  for _, g in ipairs(GROUPS) do
    local v = props[g]
    if v ~= nil then
      local ok, err = pcall(SET[g], h, v)
      if not ok then error(("%s:setProperties: %s"):format(tostring(self), tostring(err)), 2) end
    end
  end
  return self
end

---@param self fx.Vehicle
---@param props fx.VehicleProperties
---@param timeoutMs? integer
---@return fx.Promise<fx.Vehicle>
methods.setPropertiesAsync = function(self, props, timeoutMs)
  return self:takeControlAsync(timeoutMs):next(function(v) return v:setProperties(props) end)
end


local proxy, handleOf = rt.proxy, rt.proxyHandle

getters.mods = proxy("mods", {
  ---@param p fx.VehicleModsProxy
  ---@param key string
  ---@return integer
  count = function(p, key)
    local h = handleOf(p)
    local slot = slotOf(key, "vehicle.mods:count")
    if TOGGLE[key] then return 1 end
    kit(h)
    return GetNumVehicleMods(h, slot)
  end,
  ---@param p fx.VehicleModsProxy
  ---@param key string
  ---@param index? integer
  ---@return string?
  label = function(p, key, index) return modLabel(handleOf(p), key, index) end,
  ---@param p fx.VehicleModsProxy
  ---@param key string
  ---@return { index: integer, label: string? }[]
  list = function(p, key)
    local h = handleOf(p)
    local slot = slotOf(key, "vehicle.mods:list")
    local out = {}
    if TOGGLE[key] then return out end
    kit(h)
    for i = 0, GetNumVehicleMods(h, slot) - 1 do out[#out + 1] = { index = i, label = modLabel(h, key, i) } end
    return out
  end,
  ---@param p fx.VehicleModsProxy
  ---@param key? string
  ---@return fx.VehicleModsProxy
  reset = function(p, key)
    local h = handleOf(p)
    if key ~= nil then
      slotOf(key, "vehicle.mods:reset")
      if TOGGLE[key] then setMod(h, key, false) else setMod(h, key, -1) end
      return p
    end
    for _, m in ipairs(MODS) do
      if m[3] then setMod(h, m[1], false) else setMod(h, m[1], -1) end
    end
    return p
  end,
  ---@param p fx.VehicleModsProxy
  ---@return fx.VehicleModsData
  get = function(p) return getMods(handleOf(p)) end,
  ---@param p fx.VehicleModsProxy
  ---@param t fx.VehicleModsData
  ---@return fx.VehicleModsProxy
  set = function(p, t) setMods(handleOf(p), t); return p end,
}, function(h, k)
  if k == "wheelType" then return GetVehicleWheelType(h) end
  if k == "customTyres" then return GetVehicleModVariation(h, 23) end
  return getMod(h, k)
end, function(h, k, v)
  if k == "wheelType" then SetVehicleWheelType(h, rt.int(v))
  elseif k == "customTyres" then setMods(h, { customTyres = v })
  else setMod(h, k, v) end
end)

getters.colors = proxy("colors", {
  ---@param p fx.VehicleColorsProxy
  ---@return fx.VehicleColorsData
  get = function(p) return getColors(handleOf(p)) end,
  ---@param p fx.VehicleColorsProxy
  ---@param t fx.VehicleColorsData
  ---@return fx.VehicleColorsProxy
  set = function(p, t) setColors(handleOf(p), t); return p end,
}, function(h, k) return colorOf(k, "vehicle.colors").get(h) end,
  function(h, k, v) colorOf(k, "vehicle.colors").set(h, v) end)

getters.extras = proxy("extras", {
  ---@param p fx.VehicleExtrasProxy
  ---@return integer[]
  list = function(p)
    local h, out = handleOf(p), {}
    for id = 0, 20 do if DoesExtraExist(h, id) then out[#out + 1] = id end end
    return out
  end,
  ---@param p fx.VehicleExtrasProxy
  ---@return table<integer, boolean>
  get = function(p) return getExtras(handleOf(p)) end,
  ---@param p fx.VehicleExtrasProxy
  ---@param t table<integer|string, boolean>
  ---@return fx.VehicleExtrasProxy
  set = function(p, t) setExtras(handleOf(p), t, true); return p end,
}, function(h, k)
  local id = extraId(k, "vehicle.extras")
  if not DoesExtraExist(h, id) then return nil end
  return IsVehicleExtraTurnedOn(h, id)
end, function(h, k, v) setExtras(h, { [k] = v }, true) end)

getters.damage = proxy("damage", {
  ---@param p fx.VehicleDamageProxy
  ---@return fx.VehicleDamageData
  get = function(p) return getDamage(handleOf(p)) end,
  ---@param p fx.VehicleDamageProxy
  ---@param t fx.VehicleDamageData
  ---@return fx.VehicleDamageProxy
  set = function(p, t) setDamage(handleOf(p), t); return p end,
  ---@param p fx.VehicleDamageProxy
  ---@return fx.VehicleDamageProxy
  repair = function(p)
    local h = handleOf(p)
    -- SET_VEHICLE_FIXED does nothing while the engine is destroyed
    SetVehicleEngineHealth(h, 1000.0); SetVehicleBodyHealth(h, 1000.0); SetVehiclePetrolTankHealth(h, 1000.0)
    SetVehicleFixed(h); SetVehicleDeformationFixed(h)
    return p
  end,
  ---@param p fx.VehicleDamageProxy
  ---@param door integer
  ---@param remove? boolean
  ---@return fx.VehicleDamageProxy
  breakDoor = function(p, door, remove) SetVehicleDoorBroken(handleOf(p), rt.int(door), remove == true); return p end,
  ---@param p fx.VehicleDamageProxy
  ---@param window integer
  ---@return fx.VehicleDamageProxy
  smashWindow = function(p, window) SmashVehicleWindow(handleOf(p), rt.int(window)); return p end,
  ---@param p fx.VehicleDamageProxy
  ---@param window integer
  ---@return fx.VehicleDamageProxy
  fixWindow = function(p, window) FixVehicleWindow(handleOf(p), rt.int(window)); return p end,
  ---@param p fx.VehicleDamageProxy
  ---@param tyre integer
  ---@param onRim? boolean
  ---@return fx.VehicleDamageProxy
  burstTyre = function(p, tyre, onRim) SetVehicleTyreBurst(handleOf(p), rt.int(tyre), onRim == true, 1000.0); return p end,
  ---@param p fx.VehicleDamageProxy
  ---@param tyre integer
  ---@return fx.VehicleDamageProxy
  fixTyre = function(p, tyre) SetVehicleTyreFixed(handleOf(p), rt.int(tyre)); return p end,
}, function(h, k)
  damageKey(k, "vehicle.damage")
  return getDamage(h)[k]
end, function(h, k, v)
  damageKey(k, "vehicle.damage")
  setDamage(h, { [k] = v })
end)

end

return rt.finalize(T)
